-- =====================================================================
-- SE-EWRS -- synthetic benchmark dataset (NOT demo data)
--
-- Generates a dataset roughly 170x the demo -- 2,000 students, 60
-- courses, 6,000 enrolments and ~444,000 fact rows -- so the
-- performance figures in docs/database_design.md section 9 can be
-- reproduced rather than taken on trust.
--
--   Run it with database/scale_test.sh, which creates the schema first.
--
-- SAFETY: this script writes to `se_ewrs_scale` and never to `se_ewrs`.
-- It is a benchmark fixture: the rows are generated by arithmetic on
-- row numbers, the names are obviously synthetic, and the staff accounts
-- carry a placeholder password hash that cannot be logged into. Do not
-- point an application at this database expecting meaningful data.
--
-- The rows are generated with INSERT ... SELECT off a numbers table
-- rather than inserted one at a time by a client, which is why 444,000
-- rows load in about a minute.
-- =====================================================================
USE se_ewrs_scale;
DROP TABLE IF EXISTS nums;
CREATE TABLE nums (n INT PRIMARY KEY);
INSERT INTO nums (n)
SELECT a.d + b.d*10 + c.d*100 + d.d*1000 + e.d*10000
  FROM (SELECT 0 d UNION SELECT 1 UNION SELECT 2 UNION SELECT 3 UNION SELECT 4
        UNION SELECT 5 UNION SELECT 6 UNION SELECT 7 UNION SELECT 8 UNION SELECT 9) a,
       (SELECT 0 d UNION SELECT 1 UNION SELECT 2 UNION SELECT 3 UNION SELECT 4
        UNION SELECT 5 UNION SELECT 6 UNION SELECT 7 UNION SELECT 8 UNION SELECT 9) b,
       (SELECT 0 d UNION SELECT 1 UNION SELECT 2 UNION SELECT 3 UNION SELECT 4
        UNION SELECT 5 UNION SELECT 6 UNION SELECT 7 UNION SELECT 8 UNION SELECT 9) c,
       (SELECT 0 d UNION SELECT 1 UNION SELECT 2 UNION SELECT 3 UNION SELECT 4
        UNION SELECT 5 UNION SELECT 6 UNION SELECT 7 UNION SELECT 8 UNION SELECT 9) d,
       (SELECT 0 d UNION SELECT 1 UNION SELECT 2 UNION SELECT 3 UNION SELECT 4
        UNION SELECT 5 UNION SELECT 6 UNION SELECT 7 UNION SELECT 8 UNION SELECT 9) e;

INSERT INTO departments (dept_id, dept_code, dept_name) VALUES
  (1,'MATH','Department of Mathematics'),(2,'CSE','Department of Computer Science'),
  (3,'PHY','Department of Physics'),(4,'STA','Department of Statistics');

INSERT INTO users (user_id, full_name, email, password_hash, role, dept_id, is_active)
SELECT n, CONCAT('Staff ', n), CONCAT('staff', n, '@scale-demo.edu'),
       '$argon2id$v=19$m=65536,t=3,p=4$placeholderplaceholder$placeholderplaceholderplaceholder',
       'INSTRUCTOR', 1 + (n % 4), 1
  FROM nums WHERE n BETWEEN 1 AND 60;

INSERT INTO courses (course_pk, course_code, course_name, dept_id, semester, credits,
                     academic_term, total_sessions, is_active)
SELECT n, CONCAT('SC', LPAD(n,3,'0')), CONCAT('Scale Course ', n),
       1 + (n % 4), 1 + (n % 8), 3, '2026-ODD', 24, 1
  FROM nums WHERE n BETWEEN 1 AND 60;

INSERT INTO students (student_pk, student_id, full_name, email, dept_id, semester,
                      enrollment_year, is_active)
SELECT n, CONCAT('SC2026', LPAD(n,5,'0')), CONCAT('Scale Student ', n),
       CONCAT('student', n, '@scale-demo.edu'), 1 + (n % 4), 1 + (n % 8), 2026, 1
  FROM nums WHERE n BETWEEN 1 AND 2000;

INSERT INTO enrollments (student_pk, course_pk, enrolled_on, status)
SELECT s.n, 1 + ((s.n * 3 + k.n) % 60), CURDATE() - INTERVAL 120 DAY, 'ACTIVE'
  FROM nums s JOIN nums k ON k.n BETWEEN 0 AND 2
 WHERE s.n BETWEEN 1 AND 2000;

INSERT INTO attendance_records (enrollment_id, session_date, session_no, status, recorded_by)
SELECT e.enrollment_id, CURDATE() - INTERVAL (24 - k.n) * 3 DAY, k.n,
       CASE WHEN (e.enrollment_id + k.n) % 11 = 0 THEN 'ABSENT'
            WHEN (e.enrollment_id + k.n) % 17 = 0 THEN 'LATE'
            WHEN (e.enrollment_id + k.n) % 29 = 0 THEN 'EXCUSED'
            ELSE 'PRESENT' END,
       1 + (e.enrollment_id % 60)
  FROM enrollments e JOIN nums k ON k.n BETWEEN 1 AND 24;

INSERT INTO lms_activity_logs (enrollment_id, activity_type, activity_at, duration_minutes)
SELECT e.enrollment_id,
       CASE (e.enrollment_id + k.n) % 5
            WHEN 0 THEN 'LOGIN' WHEN 1 THEN 'RESOURCE_VIEW'
            WHEN 2 THEN 'FORUM_POST' WHEN 3 THEN 'VIDEO_WATCH' ELSE 'QUIZ_ATTEMPT' END,
       NOW() - INTERVAL ((e.enrollment_id + k.n) % 60) DAY,
       5 + ((e.enrollment_id + k.n) % 40)
  FROM enrollments e JOIN nums k ON k.n BETWEEN 1 AND 45;

INSERT INTO assessments (course_pk, title, assessment_type, max_marks, weight_percent,
                         due_at, created_by)
SELECT c.course_pk, CONCAT('Assessment ', k.n), 'ASSIGNMENT', 20, 10,
       NOW() - INTERVAL (30 - k.n * 5) DAY, 1 + (c.course_pk % 60)
  FROM courses c JOIN nums k ON k.n BETWEEN 1 AND 5;

INSERT INTO assessment_results (enrollment_id, assessment_id, marks_obtained,
                                submitted_at, submission_status, graded_at)
SELECT e.enrollment_id, a.assessment_id,
       CASE WHEN (e.enrollment_id + a.assessment_id) % 13 = 0 THEN NULL
            ELSE ROUND(4 + ((e.enrollment_id * 7 + a.assessment_id) % 17), 2) END,
       a.due_at - INTERVAL 1 DAY,
       CASE WHEN (e.enrollment_id + a.assessment_id) % 13 = 0 THEN 'MISSING'
            WHEN (e.enrollment_id + a.assessment_id) % 7  = 0 THEN 'LATE'
            ELSE 'ON_TIME' END,
       a.due_at
  FROM enrollments e JOIN assessments a ON a.course_pk = e.course_pk;

SELECT (SELECT COUNT(*) FROM enrollments) AS enrolments,
       (SELECT COUNT(*) FROM attendance_records) AS attendance,
       (SELECT COUNT(*) FROM lms_activity_logs) AS activity,
       (SELECT COUNT(*) FROM assessment_results) AS results;
